initJs:
function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = '';
  let sortDirection = 'asc';

  // 再描画関数の定義
  function renderRankingRows(rows) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted" style="text-align: center;">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map((row, index) => {
      const mape = row.予測精度 ? (100 - row.予測精度).toFixed(2) : '--';
      const rmse = row.推奨発注数量 && row.予測数量 ? Math.sqrt(Math.pow(row.推奨発注数量 - row.予測数量, 2)).toFixed(1) : '--';
      const accuracy = row.予測精度 || 0;
      const accuracyClass = accuracy >= 80 ? 'accuracy-high' : accuracy >= 60 ? 'accuracy-medium' : 'accuracy-low';

      return `
        <tr data-id="${row.id}">
          <td>${index + 1}</td>
          <td>${row.店舗名 || '--'}</td>
          <td>${row.商品名 || '--'}</td>
          <td>${row.商品カテゴリ || '--'}</td>
          <td>${mape}</td>
          <td>${rmse}</td>
          <td class="${accuracyClass}">${accuracy.toFixed(1)}%</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細分析</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // サマリー情報の更新
  function updateSummary(data) {
    if (!data || data.length === 0) {
      container.querySelector('#summary-mape').textContent = '--%';
      container.querySelector('#summary-rmse').textContent = '--';
      container.querySelector('#summary-products').textContent = '--';
      container.querySelector('#summary-alerts').textContent = '--';
      return;
    }

    const validData = data.filter(d => d.予測精度 != null);
    const avgAccuracy = validData.length > 0 ? validData.reduce((sum, d) => sum + d.予測精度, 0) / validData.length : 0;
    const avgMape = (100 - avgAccuracy).toFixed(1);

    const rmseValues = data.filter(d => d.推奨発注数量 && d.予測数量).map(d => Math.pow(d.推奨発注数量 - d.予測数量, 2));
    const avgRmse = rmseValues.length > 0 ? Math.sqrt(rmseValues.reduce((sum, val) => sum + val, 0) / rmseValues.length).toFixed(1) : 0;

    const alertCount = validData.filter(d => d.予測精度 < 70).length;

    container.querySelector('#summary-mape').textContent = avgMape + '%';
    container.querySelector('#summary-rmse').textContent = avgRmse;
    container.querySelector('#summary-products').textContent = data.length;
    container.querySelector('#summary-alerts').textContent = alertCount;
  }

  // グラフ描画
  function drawAccuracyTrendChart(data) {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = { top: 20, right: 20, bottom: 40, left: 50 };
    const chartWidth = canvas.width - margin.left - margin.right;
    const chartHeight = canvas.height - margin.top - margin.bottom;

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin.left, margin.top);
    ctx.lineTo(margin.left, margin.top + chartHeight);
    ctx.lineTo(margin.left + chartWidth, margin.top + chartHeight);
    ctx.stroke();

    // データポイントの描画
    if (data.length > 1) {
      ctx.strokeStyle = '#3182ce';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((d, i) => {
        const x = margin.left + (i / (data.length - 1)) * chartWidth;
        const y = margin.top + chartHeight - ((d.予測精度 || 0) / 100) * chartHeight;

        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();

      // データポイント
      ctx.fillStyle = '#3182ce';
      data.forEach((d, i) => {
        const x = margin.left + (i / (data.length - 1)) * chartWidth;
        const y = margin.top + chartHeight - ((d.予測精度 || 0) / 100) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, 2 * Math.PI);
        ctx.fill();
      });
    }

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('時間', canvas.width / 2, canvas.height - 5);
    ctx.save();
    ctx.translate(15, canvas.height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('精度(%)', 0, 0);
    ctx.restore();
  }

  function drawPredictionVsActualChart(data) {
    const canvas = container.querySelector('#prediction-vs-actual-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = { top: 20, right: 20, bottom: 40, left: 50 };
    const chartWidth = canvas.width - margin.left - margin.right;
    const chartHeight = canvas.height - margin.top - margin.bottom;

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin.left, margin.top);
    ctx.lineTo(margin.left, margin.top + chartHeight);
    ctx.lineTo(margin.left + chartWidth, margin.top + chartHeight);
    ctx.stroke();

    // 予測データ（青線）
    const predictionData = data.filter(d => d.予測数量);
    if (predictionData.length > 1) {
      ctx.strokeStyle = '#3182ce';
      ctx.lineWidth = 2;
      ctx.beginPath();
      predictionData.forEach((d, i) => {
        const x = margin.left + (i / (predictionData.length - 1)) * chartWidth;
        const maxVal = Math.max(...predictionData.map(d => d.予測数量));
        const y = margin.top + chartHeight - (d.予測数量 / maxVal) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }

    // 実績データ（赤線）
    const actualData = data.filter(d => d.実績数量);
    if (actualData.length > 1) {
      ctx.strokeStyle = '#e53e3e';
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((d, i) => {
        const x = margin.left + (i / (actualData.length - 1)) * chartWidth;
        const maxVal = Math.max(...actualData.map(d => d.実績数量));
        const y = margin.top + chartHeight - (d.実績数量 / maxVal) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }

    // 凡例
    ctx.fillStyle = '#3182ce';
    ctx.fillRect(margin.left, 5, 15, 10);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測', margin.left + 20, 14);

    ctx.fillStyle = '#e53e3e';
    ctx.fillRect(margin.left + 80, 5, 15, 10);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績', margin.left + 100, 14);
  }

  // アラート表示
  function updateAlerts(data) {
    const alertList = container.querySelector('#alert-list');
    const lowAccuracyData = data.filter(d => d.予測精度 && d.予測精度 < 70);

    if (lowAccuracyData.length === 0) {
      alertList.innerHTML = '<div class="muted">現在アラートはありません</div>';
      return;
    }

    alertList.innerHTML = lowAccuracyData.map(d => `
      <div style="padding: 10px; margin-bottom: 10px; background: rgba(255, 106, 0, 0.1); border-radius: 4px;">
        <strong>${d.店舗名} - ${d.商品名}</strong><br>
        <span class="muted">予測精度: ${d.予測精度.toFixed(1)}% (閾値: 70%未満)</span>
      </div>
    `).join('');
  }

  // データ読み込みとフィルタリング
  async function loadData() {
    try {
      const [predictionData, storeData, productData] = await Promise.all([
        window.aivicApi.list(8), // 需要予測結果
        window.aivicApi.list(1), // 店舗マスタ
        window.aivicApi.list(2)  // 商品マスタ
      ]);

      if (!predictionData || !storeData || !productData) {
        showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
        return;
      }

      // データの結合
      const enrichedData = predictionData.map(pred => {
        const store = storeData.find(s => s.id === pred.店舗ID) || {};
        const product = productData.find(p => p.id === pred.商品ID) || {};
        return {
          ...pred,
          店舗名: store.店舗名,
          商品名: product.商品名,
          商品カテゴリ: product.商品カテゴリID // 簡略化
        };
      });

      currentData = enrichedData;
      applyFilters();

      // 店舗選択肢の更新
      const storeSelect = container.querySelector('#filter-store');
      storeSelect.innerHTML = '<option value="">全店舗</option>' + 
        storeData.map(s => `<option value="${s.id}">${s.店舗名}</option>`).join('');

    } catch (error) {
      showError('データの読み込み中にエラーが発生しました: ' + error.message);
    }
  }

  // フィルタ適用
  function applyFilters() {
    const period = parseInt(container.querySelector('#filter-period').value);
    const storeId = container.querySelector('#filter-store').value;
    const category = container.querySelector('#filter-category').value;

    let filteredData = [...currentData];

    // 期間フィルタ
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - period);
    filteredData = filteredData.filter(d => {
      const predDate = new Date(d.予測対象日);
      return predDate >= cutoffDate;
    });

    // 店舗フィルタ
    if (storeId) {
      filteredData = filteredData.filter(d => d.店舗ID === storeId);
    }

    // カテゴリフィルタ
    if (category) {
      filteredData = filteredData.filter(d => d.商品カテゴリ === category);
    }

    // 表示更新
    updateSummary(filteredData);
    renderRankingRows(filteredData);
    drawAccuracyTrendChart(filteredData);
    drawPredictionVsActualChart(filteredData);
    updateAlerts(filteredData);
    hideError();
  }

  // ソート機能
  function sortData(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    currentData.sort((a, b) => {
      let aVal = a[column] || '';
      let bVal = b[column] || '';

      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
      }

      aVal = aVal.toString().toLowerCase();
      bVal = bVal.toString().toLowerCase();

      if (sortDirection === 'asc') {
        return aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      } else {
        return aVal > bVal ? -1 : aVal < bVal ? 1 : 0;
      }
    });

    applyFilters();
    updateSortIndicators();
  }

  function updateSortIndicators() {
    container.querySelectorAll('.sort-indicator').forEach(indicator => {
      indicator.textContent = '↕';
    });

    if (sortColumn) {
      const indicator = container.querySelector(`#sort-${sortColumn.toLowerCase()} .sort-indicator`);
      if (indicator) {
        indicator.textContent = sortDirection === 'asc' ? '↑' : '↓';
      }
    }
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // レポート出力
  function exportReport() {
    if (!currentData || currentData.length === 0) {
      showError('出力するデータがありません');
      return;
    }

    try {
      const headers = ['店舗名', '商品名', 'カテゴリ', '予測対象日', '予測数量', '実績数量', '予測精度(%)', 'MAPE(%)', 'RMSE'];
      const csvData = currentData.map(row => [
        row.店舗名 || '',
        row.商品名 || '',
        row.商品カテゴリ || '',
        row.予測対象日 || '',
        row.予測数量 || '',
        row.実績数量 || '',
        row.予測精度 ? row.予測精度.toFixed(1) : '',
        row.予測精度 ? (100 - row.予測精度).toFixed(2) : '',
        (row.推奨発注数量 && row.予測数量) ? Math.sqrt(Math.pow(row.推奨発注数量 - row.予測数量, 2)).toFixed(1) : ''
      ]);

      const csvContent = '\uFEFF' + [headers, ...csvData].map(row => 
        row.map(field => `"${field}"`).join(',')
      ).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `prediction_accuracy_report_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      showError('レポート出力に失敗しました: ' + error.message);
    }
  }

  // 初期データ読み込み
  loadData();

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);
  container.querySelector('#btn-export-report').addEventListener('click', exportReport);

  // 検索機能
  container.querySelector('#btn-search-ranking').addEventListener('click', () => {
    const keyword = container.querySelector('#search-ranking').value.toLowerCase();
    const filteredData = currentData.filter(row => 
      (row.商品名 || '').toLowerCase().includes(keyword) ||
      (row.店舗名 || '').toLowerCase().includes(keyword)
    );
    renderRankingRows(filteredData);
  });

  // ソートイベント
  ['rank', 'store', 'product', 'category', 'mape', 'rmse', 'accuracy'].forEach(col => {
    const header = container.querySelector(`#sort-${col}`);
    if (header) {
      header.addEventListener('click', () => {
        const columnMap = {
          'store': '店舗名',
          'product': '商品名', 
          'category': '商品カテゴリ',
          'mape': '予測精度',
          'rmse': '推奨発注数量',
          'accuracy': '予測精度'
        };
        sortData(columnMap[col] || col);
      });
    }
  });

  // 行レベル操作
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細分析画面への遷移（実装されていない場合のプレースホルダー）
      alert(`商品ID: ${id} の詳細分析画面に遷移します`);
    }
  });
}
